package com.bananalab.lite;
import android.content.*;
import org.json.*;import java.util.*;
/** Self-test of the installed app: run once in the background after each update and on request.
 *  It checks that the parts load and behave on fixed inputs; it does not prove every feature. */
final class SelfCheck{
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-self-check",0);}
 interface Step{void run()throws Exception;}
 static void must(boolean ok,String what){if(!ok)throw new IllegalStateException(what);}
 /** Name of each check with its code; pure checks can run on any JVM, the others need the installed assets. */
 static LinkedHashMap<String,Step> steps(final Context c){LinkedHashMap<String,Step> s=new LinkedHashMap<>();
  s.put("Reglas de enlaces y subenlaces",new Step(){public void run()throws Exception{java.net.URL base=new java.net.URL("https://www.example.com/docs/a.html");must("https://www.example.com/c".equals(PageCrawl.resolve(base,"/c"))&&PageCrawl.resolve(base,"/a.pdf")==null&&PageCrawl.key("https://www.example.com/a/").equals(PageCrawl.key("https://example.com/a")),"resolución de enlaces");must(PageCrawl.wanted("lee https://example.com y sus subenlaces")&&!PageCrawl.wanted("https://example.com/niveles"),"pedido de subenlaces");must("https://example.com/x".equals(PageLinks.extract("mira https://example.com/x.")),"lectura de un enlace en la frase");}});
  s.put("Pedidos del cuaderno",new Step(){public void run()throws Exception{must(KnowledgeNotebook.parse("que aprendiste").kind.equals("status")&&KnowledgeNotebook.parse("estado del lector").kind.equals("reader_status")&&KnowledgeNotebook.parse("aprende que el motor se llama nucleo naranja").kind.equals("teach"),"rutas de aprendizaje");}});
  s.put("Filtro de ejemplos Java",new Step(){public void run()throws Exception{must(CodeBank.looksJava("public class A {\n int valor() {\n  return 1;\n }\n}\n// ejemplo completo")&&!CodeBank.looksJava("function f(){ console.log(1); return 2; } // javascript"),"detección de Java");}});
  s.put("Extracción de texto de una página",new Step(){public void run()throws Exception{PageReader.Document d=PageReader.document("https://example.com/a","<html><head><title>Manual</title></head><body><nav>menu</nav><main><p>La fulgorina es un mineral ficticio que ilumina jardines de prueba.</p><a href='/b'>b</a></main></body></html>",true);must(d.title.equals("Manual")&&d.text.contains("fulgorina")&&!d.text.contains("menu")&&d.links.contains("/b"),"texto, título y enlaces");}});
  s.put("Búsqueda en lo guardado",new Step(){public void run()throws Exception{JSONArray rows=new JSONArray().put(new JSONObject().put("id","a").put("title","t").put("source","https://example.com").put("origin","web").put("saved",1L).put("truncated",false).put("text","La fulgorina es un mineral ficticio que ilumina jardines de prueba. Otra oración sin relación con el tema."));String a=ReadingKnowledge.answer(rows,"que es la fulgorina");must(a!=null&&a.contains("mineral ficticio"),"respuesta extraída");}});
  s.put("Seguimiento y respuesta corta",new Step(){public void run()throws Exception{must(FollowUp.complete("¿Y dónde murió?","tomas rivel").equals("dónde murió tomas rivel")&&FollowUp.complete("donde murio lucio maren","tomas rivel").equals("donde murio lucio maren"),"sujeto de la pregunta anterior");must("1851".equals(Lector.brief("cuando nacio tomas rivel","Tomás Rivel nació en 1851 en Altamisa."))&&"Altamisa".equals(Lector.brief("donde nacio tomas rivel","Tomás Rivel nació en 1851 en Altamisa.")),"recorte de fecha y lugar");must(Lector.plainQuestion("¿Cuándo nació?").equals("cuando nacio")&&Lector.matter("cuando murio")>=0&&!Lector.speaksOf(Lector.matter("cuando murio"),"Nació en 1802."),"asunto de la pregunta");}});
  s.put("Dos pasos y contradicciones",new Step(){public void run()throws Exception{String[] parts=LectorChain.split("¿Cuándo nació quien construyó el faro Brumel?");must(parts!=null&&parts[1].equals("cuando nacio %s")&&"Tomás Rivel".equals(LectorChain.name("El faro fue construido por Tomás Rivel en 1890.","faro")),"pregunta en dos pasos");must("figures".equals(SourceConflicts.differ("mide 3 metros","mide 9 metros"))&&SourceConflicts.differ("una planta azul","una planta azul de tallo corto")==null,"diferencia entre fuentes");}});
  s.put("Recorrido, PDF y ajuste propio",new Step(){public void run()throws Exception{must("status".equals(CrawlJob.parse("como va el recorrido"))&&"volcanes".equals(CrawlJob.topic("explora internet sobre volcanes"))&&CrawlJob.fingerprint("Hola, Mundo").equals(CrawlJob.fingerprint("hola mundo")),"recorrido y exploración");must(new String(PdfText.ascii85("87cURD]i,\"Ebo80~>".getBytes("UTF-8")),"UTF-8").equals("Hello World!"),"decodificación de PDF");List<SelfTune.Case> cases=new ArrayList<>();cases.add(new SelfTune.Case(true,true,.95));cases.add(new SelfTune.Case(false,true,.75));must(SelfTune.choose(cases)==.8&&SelfTune.value(cases,.7)==0&&SelfTune.value(cases,.8)==1,"ajuste del nivel de seguridad");}});
  s.put("Biblioteca de documentos",new Step(){public void run()throws Exception{NotebookDisk disk=NotebookDisk.of(c);must(disk.index.count()>=0&&disk.index.bytes()>=0,"índice de la biblioteca");}});
  s.put("Modelo de chat propio",new Step(){public void run()throws Exception{BananaTransformer m=TransformerBrain.load(c);must(m.vocabSize>=262&&!m.generate("hola",new ArrayList<String[]>()).text.trim().isEmpty(),"carga y generación de Chat");}});
  s.put("Lector neuronal",new Step(){public void run()throws Exception{BananaTransformer m=Lector.load(c);String text="la niña comió ñoquis, ¿sí?";must(m.bytePairs.decode(m.encode(text,200)).equals(text),"tokenizador del lector");String[] row=LectorTraining.CONTROLS[0];List<String> sentences=Arrays.asList(KnowledgeNotebook.chunks(row[0]));Lector.Pick pick=Lector.select(m,null,sentences,row[1],8);must(pick!=null,"el lector no puntuó las oraciones de control");must(sentences.get(pick.index).equals(row[2]),"el lector no eligió la oración de control (eligió: "+sentences.get(pick.index)+")");}});
  s.put("Checkpoints guardados",new Step(){public void run()throws Exception{for(String kind:new String[]{"chat","pixel","reader"})ModelDepot.open(c,kind).close();}});
  return s;}
 static final String[] PURE={"Reglas de enlaces y subenlaces","Pedidos del cuaderno","Filtro de ejemplos Java","Extracción de texto de una página","Búsqueda en lo guardado","Seguimiento y respuesta corta","Dos pasos y contradicciones","Recorrido, PDF y ajuste propio"};
 /** The checks that need no installed data, as one text: empty when all pass. Also called on freshly built code before it is packaged. */
 public static String pure(){StringBuilder problems=new StringBuilder();Map<String,Step> all=steps(null);for(String name:PURE)try{all.get(name).run();}catch(Throwable e){problems.append("\n· ").append(name).append(": ").append(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage());}return problems.toString();}
 static String isolated(Context c,String path)throws Throwable{ClassLoader loader=new dalvik.system.DexClassLoader(path,null,null,Object.class.getClassLoader());return (String)loader.loadClass("com.bananalab.lite.SelfCheck").getMethod("pure").invoke(null);}
 /** Runs the pure checks inside the code that was just built, before the update is prepared. The installed version is run the
  *  same way as a baseline: only a check that the installed code passes and the new code fails stops the build. If the
  *  mechanism itself cannot run on this device, the build continues and that is recorded. */
 static void before(Context c,byte[] dex)throws java.io.IOException{String fresh,base;java.io.File file=null;try{java.io.File dir=new java.io.File(c.getCodeCacheDir(),"self-check");dir.mkdirs();file=new java.io.File(dir,"candidate-"+UUID.randomUUID()+".dex");try(java.io.FileOutputStream out=new java.io.FileOutputStream(file)){out.write(dex);}file.setReadOnly();fresh=isolated(c,file.getAbsolutePath());base=isolated(c,c.getPackageCodePath());}catch(Throwable unavailable){prefs(c).edit().putString("before","La autoprueba previa no pudo ejecutarse en este dispositivo ("+unavailable.getClass().getSimpleName()+"); preparé la actualización sin ella.").apply();return;}finally{if(file!=null)file.delete();}
  StringBuilder broken=new StringBuilder();for(String line:fresh.split("\n"))if(!line.trim().isEmpty()&&!base.contains(line.split(":")[0]))broken.append('\n').append(line);if(broken.length()==0){prefs(c).edit().putString("before","La versión nueva pasó la autoprueba previa antes de prepararse.").apply();return;}prefs(c).edit().putString("before","La última versión que intentaste preparar no pasó la autoprueba previa.").apply();throw new java.io.IOException("El código nuevo no pasó su autoprueba y no preparé la actualización. Falla en:"+broken+"\nEstas comprobaciones pasan en la versión instalada. Deshacé la última edición de código o corregila.");}
 static String run(Context c)throws Exception{StringBuilder out=new StringBuilder();int ok=0,total=0;JSONArray failed=new JSONArray();for(Map.Entry<String,Step> step:steps(c).entrySet()){total++;try{step.getValue().run();ok++;out.append("\n✓ ").append(step.getKey());}catch(Throwable e){String why=e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();failed.put(step.getKey());out.append("\n✗ ").append(step.getKey()).append(": ").append(why.length()>160?why.substring(0,160)+"…":why);}}
  String head="Autoprueba: "+ok+" de "+total+" comprobaciones pasaron."+(ok==total?"":" Algo no funciona como en la versión de fábrica. Si esto apareció después de instalar una APK reconstruida, podés reinstalar la APK anterior; tus datos se conservan.");String text=head+out+"\nComprueba que las partes cargan y responden a entradas fijas; no prueba todas las funciones ni el comportamiento de código nuevo.";
  prefs(c).edit().putString("report",text).putInt("version",version(c)).putLong("time",System.currentTimeMillis()).putInt("failed",failed.length()).apply();return text;}
 static int version(Context c){try{return c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionCode;}catch(Throwable e){return -1;}}
 /** After an update (also a rebuilt APK) the test runs once by itself, without blocking the screen. */
 static void onOpen(final Context c){try{if(c instanceof NotebookDisk.Provider||prefs(c).getInt("version",-2)==version(c))return;prefs(c).edit().putInt("version",version(c)).apply();Thread t=new Thread(new Runnable(){public void run(){try{android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);DurableCode.awaitReady();SelfCheck.run(c);}catch(Throwable ignored){}}},"banana-self-check");t.setDaemon(true);t.start();}catch(Throwable ignored){}}
 static String last(Context c){String before=prefs(c).getString("before","");String report=prefs(c).getString("report","");if(!before.isEmpty()&&!report.isEmpty())report=report.substring(0,report.indexOf('\n')<0?report.length():report.indexOf('\n'))+" "+before+"\n";if(report.isEmpty())return "Autoprueba: todavía no se ejecutó en esta versión. Decí «hacé una autoprueba».";int line=report.indexOf('\n');return (line<0?report:report.substring(0,line))+" (decí «autoprueba» para ver el detalle)";}
}
